questionvariables.text:
/* ---------- DESIGN BACKWARDS: a parabola and a line that NEVER meet ---------- parabola y = a(x-h)^2 + k (a = 1, -1, 2 or -2: opens up or down, wide or narrow) line y = m x + n Their difference is D(x) = a x^2 + (p-m) x + (q-n) with p = -2ah, q = ah^2 + k. D has no real root exactly when n lies strictly on the "outside" of the tangent value n0 = k - m h - m^2/(4a): below n0 when the parabola opens up, above n0 when it opens down. So n = floor(n0) - s (a>0) or ceiling(n0) + s (a<0) with s = 1 or 2 gives a vertical gap of at least 1 everywhere, i.e. discriminant < 0, so there is no intersection ANYWHERE on the plane, not just on the grid. The pool [a,h,k,m,s] is vetted so that the smallest vertical gap lies inside the 16 x 16 window and the perpendicular distance from the parabola to the line is at least 0.9 (so it never looks like touching). */ pool : [ [2,-2,1,-2,2], [-2,-3,4,-2,2], [-2,1,-2,2,2], [-2,1,-3,-2,2], [2,-3,4,-2,2], [-2,0,1,1,1], [-1,1,-1,1,2], [-1,0,-2,1,2], [2,-1,-1,-1,2], [-1,3,3,0,1], [-2,0,-2,0,1], [2,-2,-4,2,2], [-1,1,-3,0,2], [-1,2,-2,1,1], [1,0,-3,0,2], [-1,-2,-2,-1,2], [1,1,2,1,1], [2,1,1,-2,2], [-2,0,-1,0,1], [2,-1,-2,1,2], [1,-1,1,1,1], [1,-2,2,-1,2], [-2,2,-2,2,2], [2,-2,2,-1,1], [2,2,-3,0,2], [1,0,-1,-1,1], [-2,1,-4,-2,2], [2,-2,0,1,2], [2,0,2,2,2], [1,0,-4,1,1], [-2,0,3,1,2], [-2,1,-3,0,1], [-2,1,-2,-1,2], [-2,2,4,0,1], [-2,1,-1,-1,2], [-1,1,-1,-1,2], [-1,0,3,-1,2], [2,1,-2,1,2], [-2,-1,-4,2,2], [-1,-2,-1,1,2], [1,0,3,-1,1], [2,-1,-2,2,2], [1,-1,2,0,1], [1,0,1,-1,2], [2,1,0,2,2], [-1,-1,-1,1,2], [-2,3,1,-1,1], [-2,2,-4,-2,2], [2,-1,3,-2,2], [-2,0,1,-1,1], [-1,-1,-1,0,1], [1,-2,-1,-1,2], [2,3,-1,-1,1], [-1,2,-4,0,2], [-2,2,2,-1,1], [-2,-1,3,1,1], [-2,0,0,1,1], [2,3,-1,0,1], [2,-1,4,-1,2], [2,3,3,0,1], [1,3,1,1,2], [1,-1,1,0,1], [1,-3,3,-1,1], [1,3,-1,1,1] ]; cfg : rand(pool); aa : cfg[1]; hh : cfg[2]; kk : cfg[3]; mm : cfg[4]; ss : cfg[5]; pp : -2*aa*hh; qq : aa*hh^2 + kk; n0 : kk - mm*hh - mm^2/(4*aa); nn : if is(aa>0) then floor(n0) - ss else ceiling(n0) + ss;
/* what the solution needs */ cq : pp - mm; /* coefficient of x in a x^2 + (p-m) x + (q-n) = 0 */ cr : qq - nn; /* constant term */ dd : cq^2 - 4*aa*cr; /* discriminant: always negative here */ xs : -cq/(2*aa); /* x where the graphs are closest */ ypar : aa*xs^2 + pp*xs + qq; ylin : mm*xs + nn; gap : abs(ypar - ylin);
/* readable equations */ sgnterm(c) := if is(c<0) then sconcat(" - ", string(-c)) else sconcat(" + ", string(c)); tm(c,v) := if is(c=0) then "" else if is(c=1) then sconcat(" + ",v) else if is(c=-1) then sconcat(" - ",v) else if is(c<0) then sconcat(" - ",string(-c),v) else sconcat(" + ",string(c),v); cn(c) := if is(c=0) then "" else sgnterm(c); lead(c,v) := if is(c=1) then v else if is(c=-1) then sconcat("-",v) else sconcat(string(c),v); rhs1 : sconcat(lead(aa,"x^2"), tm(pp,"x"), cn(qq)); rhs2 : if is(mm=0) then string(nn) else sconcat(lead(mm,"x"), cn(nn)); quad : sconcat(lead(aa,"x^2"), tm(cq,"x"), cn(cr)); eq1tex : sconcat("y = ", rhs1); eq2tex : sconcat("y = ", rhs2); xstxt : if is(xs=floor(xs)) then string(xs) else string(float(xs)); gaptxt : if is(gap=floor(gap)) then string(gap) else string(float(round(100*gap)/100));
/* part (a): radio, exactly one correct option; part (b): checkbox, statements 1, 2 and 5 are true. The order of the options is randomised with random_permutation (STACK shows them in the order of the list). */ ta1 : random_permutation([[1, true, "There is no real solution, because there is no point that lies on both graphs."], [2, false, sconcat("There is exactly one solution, where the graphs are closest, at x = ", xstxt, ".")], [3, false, "There are two solutions, one on each side of the place where the graphs are closest."], [4, false, "There are infinitely many solutions."], [5, false, "There is a solution, but it lies outside the part of the plane that is drawn."]]); ta2 : random_permutation([[1, true, "No point (x, y) satisfies both equations at the same time."], [2, true, "If the two expressions for y are set equal, the resulting quadratic equation has no real roots (its discriminant is negative)."], [3, false, "The line is a tangent to the parabola."], [4, false, "The graphs would meet if the grid were extended far enough."], [5, true, "The two equations are inconsistent: they cannot both be true for the same x and y."]]);

feedbackvariables.text:
sel : setify(ans2);
truth : {1, 2, 5};
nc : 5 - cardinality(symmdifference(sel, truth));
